15	syntax = "proto3";
16	
17	option java_multiple_files = true;
18	option java_package = "io.grpc.examples.helloworld";
19	option java_outer_classname = "HelloWorldProto";
20	option objc_class_prefix = "HLW";
21	
22	package helloworld;
23	
24	import "google/protobuf/timestamp.proto";
25	import "google/protobuf/duration.proto";
26	
27	// The greeting service definition.
28	service Greeter {
29	  // Sends a greeting
30	  rpc SayHello (HelloRequest) returns (HelloReply) {}
31	}
32	
33	// The request message containing the user's name.
34	message HelloRequest {
35	  string name = 1;
36	  google.protobuf.Timestamp request_initiation = 2;
37	}
38	
39	// The response message containing the greetings
40	message HelloReply {
41	  string message = 1;
42	  google.protobuf.Duration request_duration = 2;
43	}
